"""Skill-routed durable evidence update after the bounded 12/4 expansion is complete."""
from pathlib import Path
import sys,re,json
ROOT=Path(__file__).resolve().parents[2]
sys.path.insert(0,str(ROOT/'src/preprocessing'))
from prepare_reference_expansion_12_4 import REPORT,HUMAN
from prepare_sfincs_cpu_build import dump,sha

def main():
 r=ROOT/REPORT;s=json.loads((r/'summary.json').read_text());assert s['all16_numerically_qualified']and not s['pending']and not s['held'];p=ROOT/'docs/AnaSOP.md';backup=r/'previous-AnaSOP.md'
 if not backup.exists():backup.write_bytes(p.read_bytes())
 before=backup.read_text();parts=re.split(r'(?=^## [1-8]\. )',before,flags=re.M);assert all(any(x.startswith('## '+str(k)+'.')for x in parts)for k in [1,3,4,8])
 additions={3:'A subsequent bounded expansion now provides qualified regular-grid responses for twelve training and four validation parent candidates. Six previously qualified parents are reused and ten missing responses are newly simulated in five audited batches. The four prescribed temporal rainfall shapes each contribute three training and one validation parent. Two open controls remain in their existing legacy lineage and are not additional independent parents. The selected training inputs span peak rain rates of 23.14 to 99.78 mm/h, total rainfall of approximately 6.03 to 40.09 mm, durations of 33 to 90 minutes and stage increments of 0 to 1.384 m. Validation durations remain limited to 36 to 54 minutes, with meaningful stage-peak lag limited to -23 to 6 minutes. Each response retains forty-nine field snapshots and native-clock and volume diagnostics. The fourth batch resumes from a user-requested in-memory pause without hydraulic restarts; its two original monotonic-clock elapsed readings are affected by the pause and are excluded from performance comparisons. The current response index now records eighteen completed descendants of the original fifty-eight-run plan, including the two open controls; forty remain unrun, comprising thirty-two regular-grid and eight adaptive descendants. Source curves, geometry, earlier frozen deliveries and partitions remain unchanged. These are synthetic parent candidates and candidate numerical references, not measured-event validation, sufficient learning diversity or trained-surrogate evidence.',5:'The approved intermediate sample now contains twelve training and four validation parent candidates retained within their original partitions. Keep the previously qualified four training and two validation parents, then select the remaining eight training and two validation parents using input-only greedy maximum-minimum distance under fixed temporal-shape quotas. The selection uses rain peak, total rain, duration, stage amplitude and meaningful peak lag, with selection-only scaling within the original candidate partition. Omit lag from a pairwise distance when either prescribed stage pulse is absent. No depth response, admission outcome or learning score determines inclusion; do not replace a held event based on its response. Complete normalized-shape checks and freeze selection before new responses. This is an intermediate coverage tranche, not random sampling from an observed storm population or a new causal design.',6:'All sixteen selected parent responses now pass the original numerical event checks under the same qualified solver correction and fixed geometry. Retain each response\'s original exact, narrow-interval, wide-interval and quarantined support, including assumed-barrier contact and native shallow censoring. Source curves, roof allocation and event lineage are unchanged. The five batches audit decoded rainfall seconds and step integration, actual clocks, same-step water accounting, native positivity, closed-face zero exchange and output correspondence before advancing. Input-space coverage improves under the declared selection distance, but sixteen synthetic parent candidates do not establish statistical independence, learning sufficiency or surrogate skill. Formal training admission, learned normalization, sealed-response access and model fitting remain closed. No new formula, final variable, architecture comparison or formal grid-convergence claim is added.',7:'The intermediate twelve-training/four-validation response tranche is now complete: reuse six qualified parents, freeze ten missing regular-grid inputs, execute five finite batches and audit both cases before moving to the next batch. Preserve the complete original forcing catalog and historical execution snapshots; use the new combined execution index for current completion state. The next separately scoped research decision concerns candidate-response admission and whether to begin a bounded learning experiment or extend the remaining original training/validation coverage. Neither action is automatically authorized by completion of this tranche. Keep the forty remaining planned descendants, sealed tests and challenge responses closed. Continue to interpret Scenario coverage and split audit and Reference uncertainty as setup evidence; active measures remain the fifth milestone after the first four milestones.'}
 for i,part in enumerate(parts):
  if part.startswith('## '):
   k=int(re.match(r'## (\d)',part).group(1))
   if k in additions:parts[i]=part.rstrip()+'\n\n'+additions[k]+'\n\n'
 after=''.join(parts);assert after.isascii();p.write_text(after);dump(r/'anasop-update.json',{'sections_changed':[3,5,6,7],'skills':['data-briefing','estimation-framework-planning'],'human_record':HUMAN,'prior_sha256':sha(backup),'current_sha256':sha(p),'new_final_variables':0,'new_formulas':0,'other_sections_unchanged':True,'outputs':'Scenario coverage and split audit; Reference uncertainty','training':False});print('AnaSOP Sections3,5,6,7 updated; English/ASCII; remaining sections unchanged.')
if __name__=='__main__':main()
